def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if budget <= 0:
        return 0.0

    # Estimate market tightness: with supply 15-25 and req 13, usually 1 winner, sometimes 2.
    likely_units = max(1, int(supply / WATER_REQ))
    dangerous_opps = []
    prev_bids = []
    rich_prev_bids = []

    for opp in alive_opps:
        if opp.get('budget', 0) > 0:
            dangerous_opps.append(opp)
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) >= DAILY_SALARY:
                rich_prev_bids.append(float(bid))

    if not dangerous_opps:
        return float(min(budget, DAILY_SALARY * 0.25))

    max_prev = max(prev_bids) if prev_bids else 0.0
    rich_max_prev = max(rich_prev_bids) if rich_prev_bids else max_prev

    critical = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1
    very_tight = likely_units <= 1

    # Base target from yesterday's pressure.
    if rich_max_prev >= 120:
        target = 121.5
    elif rich_max_prev >= 100:
        target = rich_max_prev + 2.0
    elif rich_max_prev >= 80:
        target = rich_max_prev + 1.5
    elif rich_max_prev > 0:
        target = max(DAILY_SALARY * 0.72, rich_max_prev + 1.0)
    else:
        target = DAILY_SALARY * 0.6

    # Conserve when healthy; spike when survival is threatened.
    if critical:
        if very_tight:
            bid = max(target, DAILY_SALARY * 1.75)
        else:
            bid = max(target, DAILY_SALARY * 1.1)
    elif pressured:
        if very_tight:
            bid = max(target, DAILY_SALARY * 1.3)
        else:
            bid = max(target, DAILY_SALARY * 0.95)
    else:
        if very_tight:
            bid = min(target, DAILY_SALARY * 0.78)
        else:
            bid = min(target, DAILY_SALARY * 0.55)

    # Late game: if still healthy, preserve budget; if weak, buy survival.
    if day >= 8:
        if hp >= 5 and no_water == 0:
            bid = min(bid, DAILY_SALARY * 0.65)
        else:
            bid = max(bid, DAILY_SALARY * 1.0)

    # If one opponent looks desperate from yesterday failure/low hp, modestly increase.
    for opp in dangerous_opps:
        prev = opp.get('previous_trace', {}) or {}
        status = prev.get('status')
        opp_hp = opp.get('hp', 0)
        opp_no_water = opp.get('no_water_days', 0)
        if status == 'lost' or opp_hp <= 2 or opp_no_water >= 2:
            bid = max(bid, target + 2.0)
            break

    return float(max(0.0, min(budget, bid)))

