def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid', None) is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    supply_pressure = 0.0
    # Convert supply to an approximate scarcity factor in [0,1]
    # Lower supply => higher pressure
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0.0:
        supply_pressure = 0.0
    if supply_pressure > 1.0:
        supply_pressure = 1.0

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Determine my urgency
    urgency = 0
    if hp <= 2:
        urgency = 2
    elif hp <= 4:
        urgency = 1
    if no_water_days >= 2:
        urgency = max(urgency, 1)
    if no_water_days >= 4:
        urgency = 2

    # Baseline bid tuned to medium scenario and observed aggressive spending
    # Cindy spent ~95 avg and survived; so we should not go too low.
    base = DAILY_SALARY * (0.65 + 0.15 * supply_pressure)

    # If others were bidding very high yesterday, slightly raise to avoid losing the allocation
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base *= 1.10

    # Escalate sharply when urgent
    if urgency == 2:
        base = DAILY_SALARY * (0.85 + 0.1 * supply_pressure)
    elif urgency == 1:
        base = DAILY_SALARY * (0.75 + 0.08 * supply_pressure)

    # Conservative cap based on remaining budget
    bid = min(budget, base)

    # Never bid negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

